package modelmeta

import (
	"encoding/json"
	"os"
	"reflect"
	"strconv"
	"testing"
)

// Expected values are generated by running the pinned reference's pure
// functions, not by this implementation. See scripts/check-modelmeta-reference.py.
func TestPinnedSourceDifferentialVectors(t *testing.T) {
	b, e := os.ReadFile("testdata/reference-vectors.json")
	if e != nil {
		t.Fatal(e)
	}
	var vectors map[string][][]any
	if e = json.Unmarshal(b, &vectors); e != nil {
		t.Fatal(e)
	}
	ss := func(v any) []string {
		if v == nil {
			return nil
		}
		out := []string{}
		for _, s := range v.([]any) {
			out = append(out, s.(string))
		}
		return out
	}
	n := func(v any) int64 { return int64(v.(float64)) }
	eq := func(kind string, input any, got, want any) {
		t.Helper()
		a, _ := json.Marshal(got)
		b, _ := json.Marshal(want)
		if string(a) != string(b) {
			t.Fatalf("%s(%v): got %s want %s", kind, input, a, b)
		}
	}
	for kind, rows := range vectors {
		for _, v := range rows {
			switch kind {
			case "sameModel":
				eq(kind, v[0], SameModel(v[0].(string)), v[1])
			case "window":
				eq(kind, v[0], Window(n(v[0])), v[1])
			case "inputWindow":
				r := catalogRow{}
				r.Limit.Input = n(v[0])
				r.Limit.Context = n(v[1])
				eq(kind, v[:2], r.window(), v[2])
			case "outputWithin":
				eq(kind, v[:2], OutputWithin(n(v[0]), n(v[1])), v[2])
			case "kinds":
				eq(kind, v[0], Kinds(ss(v[0])), v[1])
			case "nearest":
				eq(kind, v[:2], NearestEffort(v[0].(string), ss(v[1])), v[2])
			case "kept":
				eq(kind, v[:2], keptEfforts(ss(v[0]), ss(v[1])), v[2])
			case "ultra":
				eq(kind, v[:2], withUltra(v[0].(string), ss(v[1])), v[2])
			case "numberVotes":
				m := map[int64]int{}
				for k, v := range v[0].(map[string]any) {
					i, _ := strconv.ParseInt(k, 10, 64)
					m[i] = int(n(v))
				}
				eq(kind, v[0], winningNumber(m), v[1])
			case "levelVotes", "nameVotes":
				m := map[string]int{}
				for k, v := range v[0].(map[string]any) {
					m[k] = int(n(v))
				}
				if kind == "levelVotes" {
					eq(kind, v[0], winningLevels(m), v[1])
				} else {
					eq(kind, v[0], winningName(m), v[1])
				}
			default:
				t.Fatal("unknown oracle", kind)
			}
		}
	}
	if reflect.ValueOf(vectors).Len() != 11 {
		t.Fatal("incomplete oracle")
	}
}
